$compactProof=Track-File (Join-Path $root 'build/khc-causal-compact-simd-20261002/report.json') 'compact-codec-proof'
if($compactProof.before_sha256 -cne 'A98CA8C5B4ABA79F03D91171909755887DEC528AE50325F191EEA3BF63DC43CD'){throw 'Compact codec proof SHA'}
$compactJson=Get-Content -LiteralPath $compactProof.path -Raw|ConvertFrom-Json
if($compactJson.status -cne 'correctness_and_size_passed_not_timed' -or $compactJson.failure -or $compactJson.timing_used -or $compactJson.checks.Count -ne 48 -or $compactJson.invocations.Count -ne 86 -or $compactJson.identities.Count -ne 269 -or $compactJson.owned_tmp_or_reparse -ne 0 -or $compactJson.owned_pdb -ne 0 -or $compactJson.frame_bytes -ne 483496){throw 'Compact codec proof incomplete'}
if(($compactJson.variants -join ',') -cne 'native,checked,scalar,scalar-checked'){throw 'Compact codec variant matrix'}
$compactOrdinary=@($compactJson.identities|Where-Object {$_.role -ceq 'native-codec' -and $_.path -ceq $candidate.path -and $_.before_sha256 -ceq $candidate.before_sha256 -and $_.bytes -eq 243712})
if($compactOrdinary.Count -ne 1){throw 'Candidate not the compact ordinary codec'}
$compactRefusals=@($compactJson.invocations|Where-Object exit -ne 0)
if($compactRefusals.Count -ne 8 -or @($compactRefusals|Where-Object {$_.exit -ne 1 -or !$_.stderr -or $_.stdout}).Count -or @($compactJson.invocations|Where-Object {$_.exit -eq 0 -and $_.stderr}).Count){throw 'Compact codec invocation mismatch'}
$compactDiagnostic=$compactJson.compact_diagnostic
if($compactDiagnostic.heavy_events -ne 3223156 -or ($compactDiagnostic.encode|ConvertTo-Json -Compress) -cne ($compactDiagnostic.decode|ConvertTo-Json -Compress)){throw 'Compact actual kernel diagnostic mismatch'}
if($compactDiagnostic.encode.compact_groups -ne 12892624 -or $compactDiagnostic.encode.fallback_groups -ne 0 -or $compactDiagnostic.encode.compact_option_bytes -ne 40 -or $compactDiagnostic.encode.plain_array_bytes -ne 32 -or $compactDiagnostic.encode.legacy_array_bytes -ne 96){throw 'Compact actual kernel coverage/layout'}
$compactNumericProof=Track-File (Join-Path $root 'build/khc-compact-simd-20261002-coverage-repair/report.json') 'compact-numeric-proof'
if($compactNumericProof.before_sha256 -cne 'C8B6DAA9DEFA6C97D6DD062682AA87139B0CC6C5F6782B642EA977783FCE4935'){throw 'Compact numeric proof SHA'}
$compactNumericJson=Get-Content -LiteralPath $compactNumericProof.path -Raw|ConvertFrom-Json
if($compactNumericJson.status -cne 'compact_batch_numeric_verified_not_codec_or_timing' -or $compactNumericJson.failure -or $compactNumericJson.timing_used -or $compactNumericJson.checks.Count -ne 32 -or $compactNumericJson.invocations.Count -ne 87 -or $compactNumericJson.identities.Count -ne 13 -or $compactNumericJson.owned_tmp_or_reparse -ne 0 -or !$compactNumericJson.features.avx2_available -or $compactNumericJson.summaries.Count -ne 4){throw 'Compact numeric proof incomplete'}
foreach($call in $compactNumericJson.invocations){
    $expectedExit=if($call.argv.Count -eq 0 -or ($call.argv.Count -gt 2 -and $call.argv[0] -ceq 'query' -and $call.argv[2] -ceq '-1')){2}else{0}
    if($call.exit -ne $expectedExit -or ($expectedExit -eq 0 -and $call.stderr) -or ($expectedExit -ne 0 -and (!$call.stderr -or $call.stdout))){throw 'Compact numeric invocation failure'}
}
$compactMatrix=@($compactNumericJson.summaries|ForEach-Object {"$($_.opt)/$($_.backend)"}|Sort-Object)
if(($compactMatrix -join ',') -cne '2/avx2,2/scalar,3/avx2,3/scalar'){throw 'Compact numeric matrix'}
foreach($summary in $compactNumericJson.summaries){
    $counts=$summary.summary
    if($counts.records -ne 9293629 -or $counts.matched -ne 9293629 -or $counts.batches -ne 2323408 -or $counts.compact -ne 8398832 -or $counts.certificate_fallback -ne 0 -or $counts.fingerprint_u64 -cne 'f02dbdcb00adbe1d'){throw 'Compact numeric coverage mismatch'}
    if(($counts|ConvertTo-Json -Compress) -cne ($compactNumericJson.summaries[0].summary|ConvertTo-Json -Compress)){throw 'Compact numeric summary mismatch'}
}
$report['compact_proofs']=[ordered]@{codec=$compactProof;numeric=$compactNumericProof}

$report['historical_budget_guard_repairs']=
